import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let A_1, A_2, ..., A_[n] be the vertices of a regular [n]-gon. How many distinct squares in the plane of the polygon have at least two vertices in the set {A_1, A_2, ..., A_[n]}?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose n to produce both cases (n divisible by 4 and not) with decent frequency
# Keep n reasonably large to avoid trivial instances
if rng.random() < 0.5:
    # n divisible by 4, at least 12
    d = rng.randint(3, 50)  # 12..200
    n = 4 * d
else:
    n = rng.randint(9, 200)
    # ensure not divisible by 4 for variety
    if n % 4 == 0:
        # perturb slightly while keeping n >= 9
        n += 1 if rng.random() < 0.5 else -1
        if n < 9:
            n = 9
return {'n': n}

    def verifier(assign):
# Validate domain and recompute answer
n = assign.get('n')
if not isinstance(n, int):
    # invalid type
    return (False, None)
if n < 3:
    # too small to define a regular n-gon meaningfully
    return (False, None)
# For any unordered vertex pair, there are exactly 3 squares through the pair:
# two having the segment as a side, and one having it as a diagonal.
# Thus total pair-square incidences = 3 * C(n, 2).
# Distinct squares that hit k vertices from the set contribute C(k,2) incidences.
# A square cannot meet exactly 3 vertices of the set; if it meets 4, it is an inscribed square,
# which exists iff 4 | n, and the number of such squares is n/4.
# Hence, with S4 = n/4 if 4|n else 0, we have:
# 3*C(n,2) = S2*1 + S4*6, and the total number of distinct squares is N = S2 + S4 = 3*C(n,2) - 5*S4.
try:
    from math import comb
except Exception:
    # comb is available in Python 3.8+; in older versions, fall back
    def comb(a, b):
        from math import factorial
        if b < 0 or b > a:
            return 0
        return factorial(a) // (factorial(b) * factorial(a - b))
total_inc = 3 * comb(n, 2)
s4 = (n // 4) if (n % 4 == 0) else 0
answer = total_inc - 5 * s4
# Basic sanity: answer must be positive and integral
if not isinstance(answer, int) or answer <= 0:
    return (False, None)
# Additional non-triviality check: ensure instance isn't degenerate
# For n >= 9 this always holds; still assert a modest lower bound
if answer < 3 * n:
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

